window.bot_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

const mkBtn=(lbl,w,ht,fill,bord,tc)=>{
  fill=fill||0x1a3a0a;bord=bord||0x3a7a1a;tc=tc||'#90d040';
  const bg=new A();bg.beginFill(fill,1);bg.lineStyle(1,bord);bg.drawRoundedRect(0,0,w,ht,4);bg.endFill();
  const t=new z(lbl,{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:tc,align:'center',wordWrap:true,wordWrapWidth:w-6});
  t.anchor.set(0.5,0.5);t.x=w/2;t.y=ht/2;
  const c=new e();c.addChild(bg,t);c.interactive=true;c.buttonMode=true;
  c.on('mouseover',()=>bg.tint=0xddeecc);c.on('mouseout',()=>bg.tint=0xffffff);
  c._bg=bg;c._txt=t;return c;
};

// ── Переключатель (toggle) ─────────────────────────────────────────
bot_elements.lib.Toggle=class extends e{
  constructor(){
    super();
    this.bg=new A();this._draw(false);this.addChild(this.bg);
    this.knob=new A();this.knob.beginFill(0xffffff,1);this.knob.drawCircle(0,0,10);this.knob.endFill();
    this.knob.x=12;this.knob.y=12;this.addChild(this.knob);
    this._on=false;this.interactive=true;this.buttonMode=true;
    this.on('pointerdown',()=>this.toggle());
  }
  _draw(on){
    this.bg.clear();
    this.bg.beginFill(on?0x2a7a10:0x1a1a1a,1);
    this.bg.lineStyle(1,on?0x5ab820:0x3a3a3a);
    this.bg.drawRoundedRect(0,0,50,24,12);this.bg.endFill();
  }
  toggle(){this.setValue(!this._on);}
  setValue(v){
    this._on=v;this._draw(v);
    this.knob.x=v?38:12;
    this.emit('change',v);
  }
  get value(){return this._on;}
};

// ── Строка настройки бота ─────────────────────────────────────────
bot_elements.lib.Bot_setting=class extends e{
  constructor(){
    super();
    const bg=new A();bg.beginFill(0x080e05,0.92);bg.lineStyle(1,0x1a3010,0.6);bg.drawRoundedRect(0,0,1160,58,4);bg.endFill();this.addChild(bg);
    const ic=new z('',{fontFamily:'Arial',fontSize:28,align:'center'});ic.anchor.set(0.5,0.5);ic.x=36;ic.y=29;this[ic.name='icon_txt']=ic;this.addChild(ic);
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:14,fontWeight:'bold',fill:'#b8d840'});nt.x=70;nt.y=8;this[nt.name='name_txt']=nt;this.addChild(nt);
    const dt=new z('',{fontFamily:'Arial',fontSize:11,fill:'#4a6a2a',wordWrap:true,wordWrapWidth:900});dt.x=70;dt.y=30;this[dt.name='desc_txt']=dt;this.addChild(dt);
    const tog=new bot_elements.lib.Toggle();tog.x=1098;tog.y=17;this[tog.name='toggle']=tog;this.addChild(tog);
  }
};

// ── Лог действий бота ─────────────────────────────────────────────
bot_elements.lib.Bot_log=class extends e{
  constructor(){
    super();
    const bg=new A();bg.beginFill(0x040804,0.95);bg.lineStyle(1,0x1a3010,0.5);bg.drawRoundedRect(0,0,1160,180,4);bg.endFill();this.addChild(bg);
    const hdr=new z('ЛОГ БОТА',{fontFamily:'Southbank LT',fontSize:10,fill:'#3a5a2a',letterSpacing:2});hdr.x=10;hdr.y=6;this.addChild(hdr);
    const entries=new e();entries.x=10;entries.y=26;
    for(let i=0;i<6;i++){
      const lt=new z('',{fontFamily:'Arial',fontSize:11,fill:'#4a7a3a'});lt.y=i*24;entries['line_'+i]=lt;entries.addChild(lt);
    }
    this[entries.name='log_entries']=entries;this.addChild(entries);
  }
};

// ── Статус-плашка бота ────────────────────────────────────────────
bot_elements.lib.Bot_status=class extends e{
  constructor(){
    super();
    const bg=new A();bg.beginFill(0x080e05,0.95);bg.lineStyle(1,0x1a3010,0.6);bg.drawRoundedRect(0,0,360,60,6);bg.endFill();this.addChild(bg);
    this.dot=new A();this.dot.beginFill(0x2a2a2a,1);this.dot.drawCircle(0,0,8);this.dot.endFill();this.dot.x=26;this.dot.y=30;this.addChild(this.dot);
    const st=new z('',{fontFamily:'Southbank LT',fontSize:14,fontWeight:'bold',fill:'#6a6a6a'});st.x=44;st.y=12;this[st.name='state_txt']=st;this.addChild(st);
    const ac=new z('',{fontFamily:'Arial',fontSize:11,fill:'#3a5a3a'});ac.x=44;ac.y=34;this[ac.name='action_txt']=ac;this.addChild(ac);
    // Сессия
    const sess=new z('',{fontFamily:'Southbank LT',fontSize:10,fill:'#4a6a2a',align:'right'});sess.anchor.set(1,0.5);sess.x=350;sess.y=30;this[sess.name='session_txt']=sess;this.addChild(sess);
  }
  setActive(v){
    this.dot.tint=v?0x00ff40:0x2a2a2a;
    this.state_txt.style.fill=v?'#a0d840':'#6a6a6a';
  }
};

// ── Главное окно Бота ─────────────────────────────────────────────
bot_elements.lib.Bot_win=class extends e{
  constructor(){
    super();
    const wb=new A();wb.beginFill(0x060c04,0.97);wb.lineStyle(2,0x284a18,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();this.addChild(wb);
    const hb=new A();hb.beginFill(0x081802,1);hb.drawRect(2,2,1196,42);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x284a18,0.5);hl.moveTo(2,45);hl.lineTo(1198,45);this.addChild(hb,hl);
    const ttl=new z('БОТ',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#b8d840',letterSpacing:5,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});ttl.x=20;ttl.y=12;this.addChild(ttl);
    const sub=new z('Автоматический режим игры',{fontFamily:'Arial',fontSize:11,fill:'#3a5a2a',fontStyle:'italic'});sub.x=130;sub.y=17;this.addChild(sub);
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cl=new e();cl.addChild(cbg,ctx);cl.x=1162;cl.y=7;cl.interactive=true;cl.buttonMode=true;cl.on('mouseover',()=>cbg.tint=0xddaaaa);cl.on('mouseout',()=>cbg.tint=0xffffff);
    this[cl.name='butt_close']=cl;this.addChild(cl);
    // Статус бота
    const status=new bot_elements.lib.Bot_status();status.x=20;status.y=52;this[status.name='bot_status']=status;this.addChild(status);
    // Кнопки старт/стоп
    const start=mkBtn('▶ ЗАПУСТИТЬ',150,36,0x1e4a00,0x4a9a10,'#a0e040');start.x=400;start.y=52;this[start.name='butt_start']=start;this.addChild(start);
    const stop=mkBtn('■ ОСТАНОВИТЬ',150,36,0x3a1010,0x882222,'#e04040');stop.x=560;stop.y=52;stop.visible=false;this[stop.name='butt_stop']=stop;this.addChild(stop);
    // Настройки (6 строк)
    const sets=new e();sets.x=20;sets.y=100;
    for(let i=0;i<6;i++){
      const s=new bot_elements.lib.Bot_setting();s.y=i*64;sets['setting_'+i]=s;sets.addChild(s);
    }
    this[sets.name='settings']=sets;this.addChild(sets);
    // Лог
    const log=new bot_elements.lib.Bot_log();log.x=20;log.y=496-180;this[log.name='bot_log']=log;this.addChild(log);
  }
};

bot_elements.lib.bot_elements=class extends n{
  constructor(){super({duration:1,framerate:30});const b=new bot_elements.lib.Bot_win();this[b.name='bot_win']=b;this.addChild(b);}
};
bot_elements.stage=bot_elements.lib.bot_elements}};
